select g.season, round(1.0*sum(b.start_sum)/sum(b.drives),3) avg_start, round(1.0*sum(b.kr_yds)/nullif(sum(b.kr),0),3) kr_avg, round(1.0*sum(b.ko_tb)/sum(b.kickoffs),4) tb_rate, round(1.0*sum(b.punt_net)/nullif(sum(b.punts),0),3) punt_net, round(1.0*sum(b.punt_yds)/nullif(sum(b.punts),0),3) punt_gross, round(avg(b.punts),2) punts, round(avg(b.kickoffs),2) kos, round(1.0*sum(b.first_downs)/sum(b.drives),3) fd_drive, round(avg(b.yards),1) yards, round(1.0*sum(b.yards)/sum(b.plays),4) ypp, round(avg(b.penalty_yds),2) pen_yds, round(avg(b.turnovers),3) tov from log_games__box b join log_games g on g._row = b._parent where g.stream = 'nfl' and coalesce(g.kind,'regular') = 'regular' and coalesce(g.standin,0)=0 group by g.season order by g.season
